INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002a9',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss language and power at B2","Use Sprache und Macht vocabulary","Talk about language as ideology, linguistic discrimination, and political language"],"explanation":{"intro":"Language and power vocabulary covers political language, linguistic discrimination, and how language constructs social reality at B2.","culturalNote":"Sprache und Macht: Key thinker: Victor Klemperer (LTI — Lingua Tertii Imperii — language of the Third Reich, 1947 — how the Nazis used language to normalise ideology). Newspeak (Orwell). Pierre Bourdieu: symbolic power — language as distinction marker. Gendersprache (gendered language — Germany debate: gender star (Genderstern *), gender gap (_), neutral forms (Studierende vs. Studenten) — controversial). Framing (framing theory — how word choice constructs reality — Flüchtling vs. Geflüchteter, Steuerverschwendung vs. öffentliche Investition). Political language critique: Neusprech (Newspeak), Euphemismus (euphemism). Sprachpolitik (language politics — Germany as a pluricentric German-speaking country: Austria, Switzerland)."},"examples":[{"german":"Sprache ist nie neutral: Die Wahl zwischen ''Flüchtling'' und ''Geflüchteter'' ist keine rein stilistische, sondern eine politische Entscheidung — denn Sprache konstituiert Wirklichkeit, rahmt Wahrnehmung und verteilt symbolische Würde an die Bezeichneten auf unterschiedliche Weise.","english":"Language is never neutral: the choice between ''Flüchtling'' (refugee) and ''Geflüchteter'' (person who has fled) is not purely stylistic, but a political decision — for language constitutes reality, frames perception, and distributes symbolic dignity to those designated in different ways."},{"german":"Victor Klemperers Analyse der NS-Sprache zeigt, dass Ideologie nicht nur in programmatischen Texten lebt, sondern sich in die alltägliche Sprache einschreibt: Die Trivialisierung des Entsetzlichen und die Dramatisierung des Trivialen sind sprachliche Mechanismen, durch die eine politische Gemeinschaft ihre Wirklichkeit sukzessive umdeutet.","english":"Victor Klemperer''s analysis of Nazi language shows that ideology does not only live in programmatic texts, but inscribes itself in everyday language: the trivialisation of the terrible and the dramatisation of the trivial are linguistic mechanisms through which a political community successively reinterprets its reality."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Klemperer''s LTI, framing, and language as political power at B2."}}',
'{"items":[{"word":"konstituieren","translation":"to constitute","pronunciation":"kon-sti-too-EE-ren","example":"Wirklichkeit konstituieren."},{"word":"rahmen","translation":"to frame","pronunciation":"RAH-men","example":"Wahrnehmung rahmen."},{"word":"die Trivialisierung","translation":"trivialisation","pronunciation":"dee tri-vi-ah-li-ZEE-roong","example":"Trivialisierung des Entsetzlichen."},{"word":"umddeuten","translation":"to reinterpret","pronunciation":"OOM-doy-ten","example":"Wirklichkeit umdeuten."},{"word":"symbolisch","translation":"symbolic","pronunciation":"zim-BOH-lish","example":"Symbolische Würde."},{"word":"das Framing","translation":"framing","pronunciation":"dahs FRAY-ming","example":"Politisches Framing."}]}',
'{"title":"Sich in X einschreiben — to inscribe itself in X (language/ideology permeating daily life)","pattern":"etwas schreibt sich in X ein = something inscribes itself in X (einschreiben = to inscribe, register — reflexive + in + accusative; implies that something becomes embedded into X)","explanation":"Sich einschreiben in = to inscribe itself in (reflexive: schreibt sich...ein — separable). Ideologie schreibt sich in die alltägliche Sprache ein = Ideology inscribes itself in everyday language (the ideology embeds itself, permeates without explicit statement). The metaphor is of writing — something is written into the texture of language/culture. Compare: sich in X verankern (to anchor in X — more stable), sich in X festsetzen (to entrench in X), sich in X niederschlagen (to be reflected in X — more result-focused), X durchdringen (to permeate X — active permeation), sich in X eingraben (to dig itself into X — stronger/more resistant).","examples":[{"sentence":"Die Erfahrung der Migration schreibt sich in die Sprache ein.","translation":"The experience of migration inscribes itself in language."},{"sentence":"Gesellschaftliche Normen schreiben sich in Körperpraktiken ein.","translation":"Social norms inscribe themselves in bodily practices."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Konstituieren'' means?","options":["to constitute","to form","to create","to establish"],"correctAnswer":"to constitute"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Language is never neutral: the choice between ''Flüchtling'' and ''Geflüchteter'' is not purely stylistic, but a political decision — for language constitutes reality, frames perception, and distributes symbolic dignity to those designated in different ways.","options":["Sprache ist nie neutral: Die Wahl zwischen ''Flüchtling'' und ''Geflüchteter'' ist keine rein stilistische, sondern eine politische Entscheidung — denn Sprache konstituiert Wirklichkeit, rahmt Wahrnehmung und verteilt symbolische Würde an die Bezeichneten auf unterschiedliche Weise.","Wortwahl ist nicht neutral — Sprache kann diskriminieren oder respektieren.","''Flüchtling'' und ''Geflüchteter'' sind nicht dasselbe — die Wahl zeigt eine Haltung.","Politisches Framing bestimmt, wie wir über Flüchtlinge denken."],"correctAnswer":"Sprache ist nie neutral: Die Wahl zwischen ''Flüchtling'' und ''Geflüchteter'' ist keine rein stilistische, sondern eine politische Entscheidung — denn Sprache konstituiert Wirklichkeit, rahmt Wahrnehmung und verteilt symbolische Würde an die Bezeichneten auf unterschiedliche Weise."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Erfahrung der Migration schreibt sich in die Sprache ___.","options":["ein","an","auf","durch"],"correctAnswer":"ein"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Social norms inscribe themselves in bodily practices","wordBankItems":["Gesellschaftliche","Normen","schreiben","sich","in","Körperpraktiken","ein","."],"correctAnswer":"Gesellschaftliche Normen schreiben sich in Körperpraktiken ein ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Umddeuten'' means?","options":["to reinterpret","to relabel","to reframe","to reconsider"],"correctAnswer":"to reinterpret"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002aa',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss identity and belonging at B2","Use Identität und Zugehörigkeit vocabulary","Talk about German identity, migration, and hybrid identities"],"explanation":{"intro":"Identity and belonging vocabulary covers German national identity, hybrid identities, and the politics of belonging at B2.","culturalNote":"Identität und Zugehörigkeit: German identity: complex post-WWII. Constitutional patriotism (Verfassungspatriotismus — Habermas — pride in the Basic Law, not ethnic nation — key German intellectual invention). Leitkultur debate (dominant culture — assimilation vs. pluralism). Islamdebatte (Islam debate — German Muslims — Sarrazin controversy). Migrationshintergrund (migration background — 26% of German population). Deutsche Welle (German diaspora). Hybride Identität (hybrid identity — Feridun Zaimoglu, Navid Kermani). Doppelte Staatsangehörigkeit (dual citizenship — Germany now generally allows it). Key phrase: ''Wer bin ich?'' — identity not given but constructed. Wir-Gefühl (sense of we)."},"examples":[{"german":"Nationale Identität ist keine ethnische Gegebenheit, sondern eine diskursive Konstruktion: Sie entsteht durch gemeinsame Erzählungen, geteilte Symbole und kollektive Aushandlungen dessen, was als ''deutsch'' gilt — ein Prozess, der offen, veränderbar und umstritten ist.","english":"National identity is not an ethnic given, but a discursive construction: it arises through common narratives, shared symbols, and collective negotiations of what counts as ''German'' — a process that is open, changeable, and contested."},{"german":"Hybride Identität widersetzt sich der Logik des Entweder-oder: Menschen mit Migrationsbiografien navigieren oft zwischen mehreren kulturellen Bezugssystemen und entwickeln dabei eine Kompetenz der Mehrfachzugehörigkeit, die weder Assimilation noch Selbstausgrenzung bedeutet.","english":"Hybrid identity resists the logic of either-or: people with migration biographies often navigate between several cultural reference systems and develop in doing so a competence of multiple belonging that means neither assimilation nor self-exclusion."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss German identity, constitutional patriotism, and hybrid identities at B2."}}',
'{"items":[{"word":"die Gegebenheit","translation":"given/datum","pronunciation":"dee geh-GAY-ben-hyt","example":"Ethnische Gegebenheit."},{"word":"diskursiv","translation":"discursive","pronunciation":"dis-koor-ZEEF","example":"Diskursive Konstruktion."},{"word":"aushandeln","translation":"to negotiate","pronunciation":"OWS-han-deln","example":"Identität aushandeln."},{"word":"sich widersetzen","translation":"to resist","pronunciation":"zikh VEE-der-set-tsen","example":"Sich einer Logik widersetzen."},{"word":"die Migrationsbiografie","translation":"migration biography","pronunciation":"dee mi-gra-TSYOHNS-bi-o-grä-FEE","example":"Migrationsbiografie."},{"word":"das Bezugssystem","translation":"reference system","pronunciation":"dahs beh-TSOOKS-zis-taym","example":"Kulturelle Bezugssysteme."}]}',
'{"title":"Sich einer Logik widersetzen — to resist a logic (refusing a binary)","pattern":"sich einer Sache/Logik widersetzen = to resist something/a logic (widersetzen + dative — reflexive: setzt sich...wider; dative marks what is resisted)","explanation":"Sich widersetzen + dative = to resist, to oppose (separable reflexive: setzt sich...wider). Hybride Identität widersetzt sich der Logik des Entweder-oder = Hybrid identity resists the logic of either-or (dative: der Logik — the logic is what is resisted). Implies agency: the subject actively refuses to submit to what the dative object demands. Compare: sich einer Kategorisierung entziehen (to elude categorisation — more passive evasion), sich einer Norm verweigern (to refuse a norm — stronger refusal), kämpfen gegen (to fight against — more direct), sich behaupten gegen (to assert oneself against).","examples":[{"sentence":"Die Bewegung widersetzt sich dem Diktat des Marktes.","translation":"The movement resists the dictate of the market."},{"sentence":"Er widersetzt sich jeder Vereinfachung.","translation":"He resists any simplification."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Gegebenheit'' means?","options":["given/datum","fact","reality","condition"],"correctAnswer":"given/datum"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Hybrid identity resists the logic of either-or: people with migration biographies often navigate between several cultural reference systems and develop in doing so a competence of multiple belonging that means neither assimilation nor self-exclusion.","options":["Hybride Identität widersetzt sich der Logik des Entweder-oder: Menschen mit Migrationsbiografien navigieren oft zwischen mehreren kulturellen Bezugssystemen und entwickeln dabei eine Kompetenz der Mehrfachzugehörigkeit, die weder Assimilation noch Selbstausgrenzung bedeutet.","Hybride Identität bedeutet, zwischen mehreren Kulturen zu leben ohne sich zu assimilieren.","Menschen mit Migrationshintergrund navigieren zwischen zwei Kulturen.","Hybride Identität ist weder vollständige Assimilation noch Abgrenzung."],"correctAnswer":"Hybride Identität widersetzt sich der Logik des Entweder-oder: Menschen mit Migrationsbiografien navigieren oft zwischen mehreren kulturellen Bezugssystemen und entwickeln dabei eine Kompetenz der Mehrfachzugehörigkeit, die weder Assimilation noch Selbstausgrenzung bedeutet."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Bewegung widersetzt sich dem Diktat des ___.","options":["Marktes","Systems","Staates","Kapitals"],"correctAnswer":"Marktes"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: He resists any simplification","wordBankItems":["Er","widersetzt","sich","jeder","Vereinfachung","."],"correctAnswer":"Er widersetzt sich jeder Vereinfachung ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Aushandeln'' means?","options":["to negotiate","to bargain","to deliberate","to determine"],"correctAnswer":"to negotiate"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002ab',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss memory culture at B2","Use Erinnerungskultur vocabulary","Talk about Germany''s unique Holocaust memory culture and historical reckoning"],"explanation":{"intro":"Memory culture vocabulary covers Germany''s Erinnerungskultur, Holocaust memory, and how societies deal with difficult pasts at B2.","culturalNote":"Erinnerungskultur: Germany''s Holocaust memory (Shoah — Erinnerungsarbeit = memory work) is internationally recognised as a model. Key elements: Gedenkstätten (memorial sites — Dachau, Buchenwald, Bergen-Belsen), Mahnmale (monuments — Holocaust Mahnmal Berlin — Peter Eisenman — 2005), Holocaust-Gedenktag (27. Januar — Tag der Befreiung Auschwitz). Bildungsarbeit (educational work — mandatory in schools). Vergangenheitsbewältigung (coming to terms with the past — long German word for a unique concept). 2020s debates: Erinnerungskultur im Zeitalter der Migration (migrants from non-European countries with different histories — how to include), Israel-Gaza-Konflikt and Erinnerungskultur. Stolpersteine (stumbling stones — Gunter Demnig). Tätergesellschaft (perpetrator society)."},"examples":[{"german":"Deutschlands Erinnerungskultur gilt international als Modell für den konstruktiven Umgang mit einer verbrecherischen Staatsvergangenheit: Sie verbindet institutionalisiertes Gedenken mit Bildungsarbeit, rechtlicher Aufarbeitung und einem kulturellen Klima, das Holocaust-Relativierung kriminalisiert und historische Verantwortung als dauerhaft bindend betrachtet.","english":"Germany''s memory culture is regarded internationally as a model for constructive engagement with a criminal state past: it combines institutionalised commemoration with educational work, legal reappraisal, and a cultural climate that criminalises Holocaust relativisation and views historical responsibility as permanently binding."},{"german":"Die Frage, ob Erinnerungskultur ''vererbt'' werden kann an Einwanderer ohne familiäre Verbindung zur NS-Zeit, ist keine akademische, sondern eine gesellschaftspolitisch dringende: Sie verlangt, Erinnerung nicht ethnisch, sondern staatsbürgerlich zu verankern — als Pflicht der Zugehörigkeit zur demokratischen Gemeinschaft.","english":"The question of whether memory culture can be ''inherited'' by immigrants without a family connection to the Nazi era is not an academic but a socio-politically urgent one: it requires anchoring memory not ethnically but civically — as a duty of belonging to the democratic community."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s Erinnerungskultur, Holocaust memory, and Vergangenheitsbewältigung at B2."}}',
'{"items":[{"word":"die Aufarbeitung","translation":"reappraisal","pronunciation":"dee OWF-ar-by-toong","example":"Historische Aufarbeitung."},{"word":"das Gedenken","translation":"commemoration","pronunciation":"dahs geh-DENK-en","example":"Institutionalisiertes Gedenken."},{"word":"dauerhaft","translation":"permanently/lasting","pronunciation":"DOW-er-haft","example":"Dauerhaft bindend."},{"word":"bindend","translation":"binding","pronunciation":"BIN-dend","example":"Historisch bindend."},{"word":"staatsbürgerlich","translation":"civic","pronunciation":"SHTAHTS-bür-ger-likh","example":"Staatsbürgerlich verankern."},{"word":"die Relativierung","translation":"relativisation","pronunciation":"dee reh-lah-ti-VEER-oong","example":"Holocaust-Relativierung."}]}',
'{"title":"Als dauerhaft bindend betrachten — to view as permanently binding","pattern":"etwas als X betrachten = to view/regard something as X (betrachten als = to view as — takes accusative + als; dauerhaft bindend = permanently binding)","explanation":"Als X betrachten = to view/regard as X (betrachten + als + adjective/noun — accusative). Historische Verantwortung als dauerhaft bindend betrachten = to view historical responsibility as permanently binding. Betrachten als is a perspective or evaluative judgement. Compare: als X ansehen (to see as X — more evaluative/final), als X auffassen (to understand/interpret as X — more interpretive), als X einschätzen (to assess as X — more empirical), als X erachten (to consider as X — formal/written). The phrase ''dauerhaft bindend'' (permanently binding) is key: the responsibility does not end with generational change.","examples":[{"sentence":"Er betrachtet das Versprechen als dauerhaft bindend.","translation":"He views the promise as permanently binding."},{"sentence":"Wir betrachten diese Verpflichtung als moralisch zwingend.","translation":"We view this obligation as morally compelling."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Aufarbeitung'' means?","options":["reappraisal","processing","reckoning","coming to terms"],"correctAnswer":"reappraisal"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Germany''s memory culture is regarded internationally as a model for constructive engagement with a criminal state past: it combines institutionalised commemoration with educational work, legal reappraisal, and a cultural climate that criminalises Holocaust relativisation and views historical responsibility as permanently binding.","options":["Deutschlands Erinnerungskultur gilt international als Modell für den konstruktiven Umgang mit einer verbrecherischen Staatsvergangenheit: Sie verbindet institutionalisiertes Gedenken mit Bildungsarbeit, rechtlicher Aufarbeitung und einem kulturellen Klima, das Holocaust-Relativierung kriminalisiert und historische Verantwortung als dauerhaft bindend betrachtet.","Deutschland hat eine starke Gedenkkultur, die den Holocaust nie vergessen lässt.","Erinnerungskultur in Deutschland verbindet Gedenken, Bildung und rechtliche Verantwortung.","Deutschlands Umgang mit der NS-Vergangenheit gilt weltweit als vorbildlich."],"correctAnswer":"Deutschlands Erinnerungskultur gilt international als Modell für den konstruktiven Umgang mit einer verbrecherischen Staatsvergangenheit: Sie verbindet institutionalisiertes Gedenken mit Bildungsarbeit, rechtlicher Aufarbeitung und einem kulturellen Klima, das Holocaust-Relativierung kriminalisiert und historische Verantwortung als dauerhaft bindend betrachtet."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Er betrachtet das Versprechen als dauerhaft ___.","options":["bindend","verpflichtend","gültig","wirksam"],"correctAnswer":"bindend"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: We view this obligation as morally compelling","wordBankItems":["Wir","betrachten","diese","Verpflichtung","als","moralisch","zwingend","."],"correctAnswer":"Wir betrachten diese Verpflichtung als moralisch zwingend ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Staatsbürgerlich'' means?","options":["civic","civil","citizenship","national"],"correctAnswer":"civic"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002ac',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss generational conflict at B2","Use Generationenkonflikt vocabulary","Talk about intergenerational fairness, climate justice, and age-based social divides"],"explanation":{"intro":"Generational conflict vocabulary covers intergenerational fairness, generational stereotypes, and the politics of ageing at B2.","culturalNote":"Generationenkonflikt: Key issues in Germany: Generationengerechtigkeit (intergenerational justice — will our debts/climate leave the young worse off?), Rentenstreit (pension dispute — Umlageverfahren vs. Kapitaldeckung), Klimagerechtigkeit (climate justice — youth movement: ''ihr habt unsere Zukunft gestohlen'' — you stole our future — Greta Thunberg, Fridays for Future). Demographics: Babyboomer (born 1955-69 in Germany) entering retirement — straining pension system. Millennials and Gen Z: housing unaffordability, precarious employment, climate anxiety. Intergenerationale Solidarität (intergenerational solidarity) vs. ''OK Boomer'' backlash. Key sociological concept: Karl Mannheim''s generation theory."},"examples":[{"german":"Generationengerechtigkeit ist ein normatives Konzept, das die zeitliche Dimension sozialer Gerechtigkeit in den Blick nimmt: Es stellt die Frage, welche Schulden, Ressourcen und Schäden eine Generation der nächsten überlässt — und ob die heutige Lebensweise auf Kosten zukünftiger Generationen geht.","english":"Intergenerational justice is a normative concept that brings the temporal dimension of social justice into view: it poses the question of what debts, resources, and damages one generation leaves to the next — and whether today''s way of life is at the expense of future generations."},{"german":"Generationenkonflikte sind keine Naturkatastrophen, sondern strukturell vermittelte Interessenkollisionen: Rentengesetzgebung, Eigentumsrechte und Klimapolitik verteilen Lasten und Chancen systematisch nach Kohortenzugehörigkeit — und machen damit politische Konflikte zwischen Altersgruppen aus strukturellen Gründen wahrscheinlich.","english":"Generational conflicts are not natural catastrophes, but structurally mediated interest collisions: pension legislation, property rights, and climate policy distribute burdens and opportunities systematically according to cohort membership — and thereby make political conflicts between age groups structurally probable."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss intergenerational justice, pension debates, and climate justice at B2."}}',
'{"items":[{"word":"in den Blick nehmen","translation":"to bring into view","pronunciation":"in den BLIK NAY-men","example":"Dimension in den Blick nehmen."},{"word":"überlassen","translation":"to leave to","pronunciation":"ü-ber-LAS-sen","example":"Der nächsten Generation überlassen."},{"word":"strukturell vermittelt","translation":"structurally mediated","pronunciation":"shtru-ktu-REL fer-MIT-elt","example":"Strukturell vermittelte Konflikte."},{"word":"die Kollision","translation":"collision","pronunciation":"dee ko-li-ZYOHN","example":"Interessenkollision."},{"word":"die Kohorte","translation":"cohort","pronunciation":"dee ko-HOR-teh","example":"Kohortenzugehörigkeit."},{"word":"wahrscheinlich machen","translation":"to make probable","pronunciation":"VAHR-shyn-likh MAH-khen","example":"Konflikte wahrscheinlich machen."}]}',
'{"title":"Auf Kosten + genitive gehen — to go at the expense of (burden transfer)","pattern":"etwas geht auf Kosten + genitive = something goes at the expense of (Kosten = costs; auf Kosten = at the cost of/expense of — genitive follows)","explanation":"Auf Kosten + genitive = at the cost/expense of. Die heutige Lebensweise geht auf Kosten zukünftiger Generationen = Today''s way of life goes at the expense of future generations. The genitive marks who bears the cost (zukünftiger Generationen = of future generations). Compare: zu Lasten + genitive (to the detriment of — more formal legal), auf jemandes Kosten (at someone''s expense — idiomatic), zulasten (variant spelling). Note: auf Kosten also appears as noun: ''die Kosten'' = the costs (die Kosten tragen = to bear the costs; Kosten verursachen = to cause costs).","examples":[{"sentence":"Der Aufschwung ging auf Kosten der Umwelt.","translation":"The boom came at the expense of the environment."},{"sentence":"Einsparungen dürfen nicht auf Kosten der Qualität gehen.","translation":"Savings must not go at the expense of quality."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Strukturell vermittelt'' means?","options":["structurally mediated","structurally caused","structurally conditioned","institutional"],"correctAnswer":"structurally mediated"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Intergenerational justice is a normative concept that brings the temporal dimension of social justice into view: it poses the question of what debts, resources, and damages one generation leaves to the next — and whether today''s way of life is at the expense of future generations.","options":["Generationengerechtigkeit ist ein normatives Konzept, das die zeitliche Dimension sozialer Gerechtigkeit in den Blick nimmt: Es stellt die Frage, welche Schulden, Ressourcen und Schäden eine Generation der nächsten überlässt — und ob die heutige Lebensweise auf Kosten zukünftiger Generationen geht.","Generationengerechtigkeit fragt, ob wir unsere Probleme an die nächste Generation weitergeben.","Heutige Entscheidungen belasten zukünftige Generationen finanziell und ökologisch.","Klimagerechtigkeit ist eine Form der Generationengerechtigkeit."],"correctAnswer":"Generationengerechtigkeit ist ein normatives Konzept, das die zeitliche Dimension sozialer Gerechtigkeit in den Blick nimmt: Es stellt die Frage, welche Schulden, Ressourcen und Schäden eine Generation der nächsten überlässt — und ob die heutige Lebensweise auf Kosten zukünftiger Generationen geht."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Der Aufschwung ging auf Kosten der ___.","options":["Umwelt","Natur","Gesellschaft","Zukunft"],"correctAnswer":"Umwelt"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Savings must not go at the expense of quality","wordBankItems":["Einsparungen","dürfen","nicht","auf","Kosten","der","Qualität","gehen","."],"correctAnswer":"Einsparungen dürfen nicht auf Kosten der Qualität gehen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''In den Blick nehmen'' means?","options":["to bring into view","to focus on","to consider","to examine"],"correctAnswer":"to bring into view"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002ad',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss youth movements at B2","Use Jugendbewegungen vocabulary","Talk about German youth movements, Fridays for Future, and youth protest culture"],"explanation":{"intro":"Youth movements vocabulary covers the history of German youth movements and contemporary youth activism at B2.","culturalNote":"Jugendbewegungen: Germany has a rich youth movement history: Wandervogel (late 19th century — back to nature, hiking), Bündische Jugend, then Nazi Hitlerjugend (mandatory from 1936). Post-war: politicised youth: 68er-Bewegung (student revolts 1968 — Frankfurt School influence, Vietnam war protests, anti-authoritarianism). Hausbesetzer (squatter movement — 1980s Berlin). Anti-Atomkraft (anti-nuclear — 70s-80s). Contemporary: Fridays for Future (Greta Thunberg — Germany massive — 2019 climate strikes), Letzte Generation (Last Generation — radical climate group — gluing to roads, art). Youth as political innovators vs. radicalism fears. Landflucht/Stadtflucht (rural-urban youth migration)."},"examples":[{"german":"Jugendbewegungen entstehen historisch in gesellschaftlichen Umbruchphasen: Sie artikulieren Generationsansprüche, die die bestehende Ordnung herausfordern, und machen dabei Erfahrungen der kollektiven Handlungswirksamkeit — eine Ressource, die politische Sozialisation nachhaltig prägt.","english":"Youth movements arise historically in phases of societal upheaval: they articulate generational claims that challenge the existing order, and in doing so make experiences of collective efficacy — a resource that shapes political socialisation lastingly."},{"german":"Fridays for Future repräsentiert eine neue Form jugendlichen Aktivismus, die traditionelle Parteipolitik unterläuft: Schulstreik als Protestform, transnational vernetzte Mobilisierung und eine Sprache der existenziellen Dringlichkeit verankerten Klimapolitik dauerhaft in öffentlicher Agenda.","english":"Fridays for Future represents a new form of youth activism that undermines traditional party politics: school strike as a form of protest, transnationally networked mobilisation, and a language of existential urgency anchored climate policy permanently in the public agenda."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Fridays for Future, the 68er movement, and youth activism in Germany at B2."}}',
'{"items":[{"word":"die Handlungswirksamkeit","translation":"efficacy","pronunciation":"dee HAND-loonks-virk-zahm-kyt","example":"Kollektive Handlungswirksamkeit."},{"word":"nachhaltig prägen","translation":"to shape lastingly","pronunciation":"NAHKH-hal-tikh PRAY-gen","example":"Sozialisation nachhaltig prägen."},{"word":"unterlaufen","translation":"to undermine/undercut","pronunciation":"oon-ter-LOW-fen","example":"Parteipolitik unterlaufen."},{"word":"vernetzen","translation":"to network","pronunciation":"fer-NET-tsen","example":"Transnational vernetzt."},{"word":"die Dringlichkeit","translation":"urgency","pronunciation":"dee DRING-likh-kyt","example":"Existenzielle Dringlichkeit."},{"word":"verankern","translation":"to anchor","pronunciation":"fer-AN-kern","example":"In Agenda verankern."}]}',
'{"title":"In öffentlicher Agenda verankern — to anchor in the public agenda","pattern":"etwas in X verankern = to anchor something in X (verankern = to anchor — more permanent than ''einbetten'' (embed) or ''setzen'' (set); implies lasting structural presence)","explanation":"In X verankern = to anchor in X (verankern = to anchor — from Anker = anchor). Klimapolitik dauerhaft in öffentlicher Agenda verankern = to anchor climate policy permanently in the public agenda (to make it a permanent feature, not just temporarily in the news). Dauerhaft (permanently) amplifies the anchoring. Compare: auf der Agenda setzen (to put on the agenda — more temporary, like adding an item), in den Fokus rücken (to move into focus — more attention-based), als Priorität etablieren (to establish as a priority — more institutional), einschreiben in (to inscribe into — more textual/normative).","examples":[{"sentence":"Das Thema muss dauerhaft in der öffentlichen Debatte verankert werden.","translation":"The topic must be permanently anchored in public debate."},{"sentence":"Das Prinzip wurde in der Verfassung verankert.","translation":"The principle was anchored in the constitution."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Dringlichkeit'' means?","options":["urgency","importance","necessity","priority"],"correctAnswer":"urgency"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Fridays for Future represents a new form of youth activism that undermines traditional party politics: school strike as a form of protest, transnationally networked mobilisation, and a language of existential urgency anchored climate policy permanently in the public agenda.","options":["Fridays for Future repräsentiert eine neue Form jugendlichen Aktivismus, die traditionelle Parteipolitik unterläuft: Schulstreik als Protestform, transnational vernetzte Mobilisierung und eine Sprache der existenziellen Dringlichkeit verankerten Klimapolitik dauerhaft in öffentlicher Agenda.","Fridays for Future hat Klimapolitik dauerhaft auf die politische Agenda gebracht.","Jugendliche haben mit Schulstreiks eine neue Art politischer Beteiligung etabliert.","FFF hat bewiesen, dass Jugendliche politisch etwas bewegen können."],"correctAnswer":"Fridays for Future repräsentiert eine neue Form jugendlichen Aktivismus, die traditionelle Parteipolitik unterläuft: Schulstreik als Protestform, transnational vernetzte Mobilisierung und eine Sprache der existenziellen Dringlichkeit verankerten Klimapolitik dauerhaft in öffentlicher Agenda."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Prinzip wurde in der Verfassung ___.","options":["verankert","festgelegt","eingeschrieben","eingebettet"],"correctAnswer":"verankert"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The topic must be permanently anchored in public debate","wordBankItems":["Das","Thema","muss","dauerhaft","in","der","öffentlichen","Debatte","verankert","werden","."],"correctAnswer":"Das Thema muss dauerhaft in der öffentlichen Debatte verankert werden ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Unterlaufen'' means?","options":["to undermine/undercut","to subvert","to circumvent","to bypass"],"correctAnswer":"to undermine/undercut"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002ae',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss sport and society at B2","Use Sport und Gesellschaft vocabulary","Talk about the social functions of sport and German football culture"],"explanation":{"intro":"Sport and society vocabulary covers sport''s social functions, the German football system, and sport as politics at B2.","culturalNote":"Sport und Gesellschaft: Germany: football (Fußball) is the dominant sport — Bundesliga, DFB (German Football Association). Key: WM 2006 (World Cup — summer fairy tale — ''Sommermärchen'' — national mood-changer). National team diversity debate (Özil controversy 2018). Sportverein (sports club — 90,000 clubs — 27 million members — largest civil society institution). Turnbewegung (gymnastics movement — Friedrich Ludwig Jahn ''Turnvater'' — 19th century — nationalist). Sport as integration: integration through sport programs. Doping (NADA — anti-doping agency). Breitensport (mass sport) vs. Leistungssport (competitive sport). E-sport debate (is it sport?). Olympia-Bewerbung (Germany bidding for 2036 Munich — sensitivity given 1936 Berlin)."},"examples":[{"german":"Sport erfüllt in modernen Gesellschaften multiple soziale Funktionen: Er schafft Gemeinschaft und kollektive Identität, bietet Räume körperlicher Ausdrucksfähigkeit außerhalb des Arbeitsalltags, integriert durch gemeinsame Praxis und mobilisiert emotionale Energie auf eine Weise, die politische Systeme nur selten erreichen.","english":"Sport fulfils multiple social functions in modern societies: it creates community and collective identity, offers spaces of physical expressiveness outside working everyday life, integrates through common practice, and mobilises emotional energy in a way that political systems rarely achieve."},{"german":"Das 2006er WM-Sommermärchen markiert eine Verschiebung im deutschen Nationalgefühl: Es ermöglichte eine unverkrampfte kollektive Freude, die vom Schatten der Geschichte befreit schien — ein Moment, in dem Nationalstolz und kosmopolitische Offenheit kurzfristig zusammenfielen.","english":"The 2006 World Cup summer fairy tale marks a shift in the German sense of national feeling: it enabled an unself-conscious collective joy that seemed freed from the shadow of history — a moment in which national pride and cosmopolitan openness temporarily coincided."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss sport''s social functions, the Sommermärchen, and German football culture at B2."}}',
'{"items":[{"word":"die Ausdrucksfähigkeit","translation":"expressiveness","pronunciation":"dee OWS-drooks-fä-ikh-kyt","example":"Körperliche Ausdrucksfähigkeit."},{"word":"mobilisieren","translation":"to mobilise","pronunciation":"mo-bi-li-ZEER-en","example":"Emotionale Energie mobilisieren."},{"word":"die Verschiebung","translation":"shift","pronunciation":"dee fer-SHEE-boong","example":"Verschiebung im Nationalgefühl."},{"word":"unverkrampft","translation":"unself-conscious","pronunciation":"oon-fer-KRAMPFT","example":"Unverkrampfte Freude."},{"word":"kosmopolitisch","translation":"cosmopolitan","pronunciation":"kos-mo-po-LEE-tish","example":"Kosmopolitische Offenheit."},{"word":"zusammenfallen","translation":"to coincide","pronunciation":"tsoo-ZAM-en-fal-en","example":"Zusammenfallen von X und Y."}]}',
'{"title":"Kurzfristig zusammenfallen — to temporarily coincide (momentary alignment of opposites)","pattern":"X und Y fallen kurzfristig zusammen = X and Y temporarily coincide (zusammenfallen = separable: fallen...zusammen; kurzfristig = temporarily/short-term — marks the brevity of the coincidence; often used when two normally contrasting things briefly align)","explanation":"Zusammenfallen (separable: fallen...zusammen) = to coincide, to come together at the same point. Nationalstolz und kosmopolitische Offenheit fielen kurzfristig zusammen = National pride and cosmopolitan openness temporarily coincided. The kurzfristig (short-term/temporarily) marks that this coincidence was fleeting — suggesting the normal state is tension. Compare: sich vereinen (to unite — more active/intentional), sich überschneiden (to overlap — partial/partial), sich decken (to coincide/match — more exact/complete), übereinstimmen (to agree/coincide — more intellectual/evaluative).","examples":[{"sentence":"Ihre Interessen fallen in diesem Punkt zusammen.","translation":"Their interests coincide on this point."},{"sentence":"Die Termine fielen leider zusammen.","translation":"The appointments unfortunately coincided."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Unverkrampft'' means?","options":["unself-conscious","relaxed","uninhibited","effortless"],"correctAnswer":"unself-conscious"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The 2006 World Cup summer fairy tale marks a shift in the German sense of national feeling: it enabled an unself-conscious collective joy that seemed freed from the shadow of history — a moment in which national pride and cosmopolitan openness temporarily coincided.","options":["Das 2006er WM-Sommermärchen markiert eine Verschiebung im deutschen Nationalgefühl: Es ermöglichte eine unverkrampfte kollektive Freude, die vom Schatten der Geschichte befreit schien — ein Moment, in dem Nationalstolz und kosmopolitische Offenheit kurzfristig zusammenfielen.","Die WM 2006 zeigte, dass Deutschland offen und selbstbewusst Nationalstolz zeigen kann.","Das Sommermärchen 2006 war ein Wendepunkt in der deutschen Selbstwahrnehmung.","2006 war das erste Mal, dass Deutsche unverkrampft Nationalstolz zeigten."],"correctAnswer":"Das 2006er WM-Sommermärchen markiert eine Verschiebung im deutschen Nationalgefühl: Es ermöglichte eine unverkrampfte kollektive Freude, die vom Schatten der Geschichte befreit schien — ein Moment, in dem Nationalstolz und kosmopolitische Offenheit kurzfristig zusammenfielen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ihre Interessen fallen in diesem Punkt ___.","options":["zusammen","überein","zusammen","gleich"],"correctAnswer":"zusammen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The appointments unfortunately coincided","wordBankItems":["Die","Termine","fielen","leider","zusammen","."],"correctAnswer":"Die Termine fielen leider zusammen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Verschiebung'' means?","options":["shift","change","movement","transition"],"correctAnswer":"shift"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002af',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss travel and tourism at B2","Use Reisen und Tourismus vocabulary","Talk about sustainable tourism, over-tourism, and Germany''s travel culture"],"explanation":{"intro":"Travel and tourism vocabulary covers tourism economics, sustainable tourism, and Germany''s Reiselust at B2.","culturalNote":"Reisen und Tourismus: Germany: Weltreisemeister (world travel champion by spending per capita for decades — Reiselust). Key destinations: Mediterranean (Spain, Italy, Greece — fly and all-inclusive). Domestic: Bavaria (Alps, Oktoberfest), Berlin, Rhine Valley. Incoming tourism: Germany receives ~90M tourists p.a. Key issues: Overtourism (Barcelona, Venice, Mallorca — locals pushed out), Klimafolgen des Fliegens (flight emissions — Flugscham = flight shame), Massentourismus (mass tourism) vs. nachhaltiger Tourismus. Key concept: Trekkingurlaub vs. Kreuzfahrt (cruise ships — largest polluters). Reiseveranstalter (tour operators — TUI world''s largest). COVID impact: massive industry collapse 2020-21. Workation, Slowtravel."},"examples":[{"german":"Massentourismus ist ein Paradoxon: Er verändert, zerstört und trivialisiert häufig genau das, was er besuchen will — natürliche Landschaften, authentische Kulturen und historische Orte verlieren durch übermäßigen Zustrom ihren ursprünglichen Charakter und werden zu bloßen Konsumkulissen.","english":"Mass tourism is a paradox: it often changes, destroys, and trivialises precisely what it wants to visit — natural landscapes, authentic cultures, and historical sites lose their original character through excessive influx and become mere consumer backdrops."},{"german":"Nachhaltiger Tourismus verlangt eine grundlegende Neuausrichtung: Nicht ''möglichst viel sehen in möglichst kurzer Zeit'', sondern Tiefe statt Breite, Entschleunigung statt Maximierung und Verantwortung gegenüber dem besuchten Ort als konstitutiver Teil des Reisebegriffs.","english":"Sustainable tourism requires a fundamental reorientation: not ''see as much as possible in as short a time as possible'', but depth over breadth, slowing down over maximisation, and responsibility towards the visited place as a constitutive part of the concept of travel."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss mass tourism paradoxes, sustainable tourism, and Germany''s travel culture at B2."}}',
'{"items":[{"word":"trivialisieren","translation":"to trivialise","pronunciation":"tri-vi-ah-li-ZEER-en","example":"Kulturen trivialisieren."},{"word":"der Zustrom","translation":"influx","pronunciation":"dayr TSOO-shtrom","example":"Übermäßiger Zustrom."},{"word":"die Konsumkulisse","translation":"consumer backdrop","pronunciation":"dee kon-ZOOM-koo-li-seh","example":"Bloße Konsumkulisse."},{"word":"die Neuausrichtung","translation":"reorientation","pronunciation":"dee NOY-ows-rikh-toong","example":"Grundlegende Neuausrichtung."},{"word":"konstitutiv","translation":"constitutive","pronunciation":"kon-sti-too-TEEF","example":"Konstitutiver Teil."},{"word":"die Entschleunigung","translation":"slowing down","pronunciation":"dee ent-SHLOY-ni-goong","example":"Entschleunigung statt Maximierung."}]}',
'{"title":"Tiefe statt Breite — depth over breadth (quality over quantity tradeoff)","pattern":"Tiefe statt Breite = depth over breadth (statt = instead of — with genitive OR nominative — marking a substitution or preference: X statt Y = X instead of Y)","explanation":"Statt = instead of (with genitive: statt + genitive; but in modern German often dative or nominative in informal contexts). Tiefe statt Breite = depth instead of breadth — a conceptual tradeoff (fewer things deeply vs. many things superficially). This ''X statt Y'' pattern expresses a deliberate preference or substitution: choose X over Y. Compare: X anstelle von Y (X in place of Y — more formal/administrative), X vor Y (X before/over Y — preferential ranking), lieber X als Y (rather X than Y — more personal preference).","examples":[{"sentence":"Qualität statt Quantität sollte das Ziel sein.","translation":"Quality instead of quantity should be the goal."},{"sentence":"Langsamkeit statt Geschwindigkeit ist das Prinzip.","translation":"Slowness instead of speed is the principle."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Konsumkulisse'' means?","options":["consumer backdrop","tourist trap","spectacle","commercial facade"],"correctAnswer":"consumer backdrop"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Mass tourism is a paradox: it often changes, destroys, and trivialises precisely what it wants to visit — natural landscapes, authentic cultures, and historical sites lose their original character through excessive influx and become mere consumer backdrops.","options":["Massentourismus ist ein Paradoxon: Er verändert, zerstört und trivialisiert häufig genau das, was er besuchen will — natürliche Landschaften, authentische Kulturen und historische Orte verlieren durch übermäßigen Zustrom ihren ursprünglichen Charakter und werden zu bloßen Konsumkulissen.","Massentourismus schadet den Orten, die er besucht.","Overtourism zerstört die Authentizität von Reisezielen.","Tourismus paradoxerweise ruiniert das, was Touristen suchen."],"correctAnswer":"Massentourismus ist ein Paradoxon: Er verändert, zerstört und trivialisiert häufig genau das, was er besuchen will — natürliche Landschaften, authentische Kulturen und historische Orte verlieren durch übermäßigen Zustrom ihren ursprünglichen Charakter und werden zu bloßen Konsumkulissen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Qualität statt Quantität sollte das Ziel ___.","options":["sein","werden","bleiben","bilden"],"correctAnswer":"sein"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Slowness instead of speed is the principle","wordBankItems":["Langsamkeit","statt","Geschwindigkeit","ist","das","Prinzip","."],"correctAnswer":"Langsamkeit statt Geschwindigkeit ist das Prinzip ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Der Zustrom'' means?","options":["influx","flow","arrival","stream"],"correctAnswer":"influx"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002b0',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss housing and gentrification at B2","Use Wohnen und Gentrifizierung vocabulary","Talk about Germany''s housing crisis, rent control, and gentrification"],"explanation":{"intro":"Housing and gentrification vocabulary covers Germany''s housing crisis, rent regulation, and urban displacement at B2.","culturalNote":"Wohnen und Gentrifizierung: Germany: historically high rental rates (~52% renters — one of the highest in Europe). Key issues: Wohnungsnot (housing shortage — particularly in major cities: Berlin, Munich, Hamburg, Frankfurt). Mietpreisbremse (rent brake — 2015 — intended to limit rent increases — partially effective). Mietspiegel (rent index — local rent comparisons). Sozialer Wohnungsbau (social housing — historically 3 million units, now 1 million — dramatic decline). Gentrifizierung (gentrification — original residents displaced by affluent newcomers). WBS (Wohnberechtigungsschein — social housing eligibility certificate). Key: Right to housing debate (Wohnen als Grundrecht). Berlin 2021 Volksbegehren (referendum to expropriate large landlords — 56% yes — but declared unconstitutional)."},"examples":[{"german":"Die Wohnungskrise in deutschen Großstädten ist keine vorübergehende Marktkorrektur, sondern Ergebnis jahrzehntelanger Vernachlässigung sozialer Wohnungspolitik: Der Rückzug des Staates aus dem sozialen Wohnungsbau und Deregulierungstendenzen haben einen Markt entstehen lassen, der Wohnen zur Kapitalanlage statt zur sozialen Grundversorgung macht.","english":"The housing crisis in German cities is not a temporary market correction, but the result of decades of neglect of social housing policy: the withdrawal of the state from social housing and deregulation tendencies have allowed a market to emerge that makes housing a capital investment rather than a basic social provision."},{"german":"Gentrifizierung bezeichnet einen Prozess, der soziale Schichtung räumlich materialisiert: Aufwertung von Stadtvierteln zieht Kaufkräftige an, treibt Mieten und Bodenpreise in die Höhe und verdrängt einkommensschwache Bewohner in periphere Lagen — eine Logik, die soziale Mischung und nachbarschaftliche Solidarität systematisch untergräbt.","english":"Gentrification designates a process that spatially materialises social stratification: upgrading of urban districts attracts affluent residents, drives up rents and land prices, and displaces low-income residents into peripheral locations — a logic that systematically undermines social mixing and neighbourhood solidarity."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s housing crisis, gentrification, and rent control at B2."}}',
'{"items":[{"word":"die Vernachlässigung","translation":"neglect","pronunciation":"dee fer-NAKH-lä-si-goong","example":"Vernachlässigung der Wohnungspolitik."},{"word":"die Kapitalanlage","translation":"capital investment","pronunciation":"dee kah-pi-TAHL-an-lah-geh","example":"Wohnen als Kapitalanlage."},{"word":"die Aufwertung","translation":"upgrading","pronunciation":"dee OWF-ver-toong","example":"Aufwertung von Vierteln."},{"word":"die Kaufkraft","translation":"purchasing power","pronunciation":"dee KOWF-kraft","example":"Kaufkräftige anziehen."},{"word":"verdrängen","translation":"to displace","pronunciation":"fer-DRENG-en","example":"Bewohner verdrängen."},{"word":"peripher","translation":"peripheral","pronunciation":"peh-ri-FÄR","example":"Periphere Lagen."}]}',
'{"title":"Entstehen lassen — to allow to emerge (permissive causation)","pattern":"etwas lässt X entstehen = something allows X to emerge, causes X to come into being (lassen + infinitive = permissive/causative; entstehen = to arise; haben entstehen lassen = past causative)","explanation":"Lassen + infinitive = to allow to/cause to. X lässt Y entstehen = X allows Y to emerge (causative: X causes the emergence of Y). Haben entstehen lassen = allowed to emerge (perfect: Die Maßnahmen haben Probleme entstehen lassen = the measures allowed problems to arise). Entstehen (to arise, come into being) marks what was permitted/caused. Compare: X erzeugt Y (X produces Y — more direct cause), X führt zu Y (X leads to Y — causal chain), X ermöglicht Y (X enables Y — possibility), X schafft Y (X creates Y — active creation). Lassen (causative) vs. entstehen allein (just arise — no external causation).","examples":[{"sentence":"Die Deregulierung hat Monopole entstehen lassen.","translation":"Deregulation has allowed monopolies to emerge."},{"sentence":"Lasse keine Missverständnisse entstehen.","translation":"Do not allow any misunderstandings to arise."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Aufwertung'' means?","options":["upgrading","appreciation","improvement","enhancement"],"correctAnswer":"upgrading"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The housing crisis in German cities is not a temporary market correction, but the result of decades of neglect of social housing policy: the withdrawal of the state from social housing and deregulation tendencies have allowed a market to emerge that makes housing a capital investment rather than a basic social provision.","options":["Die Wohnungskrise in deutschen Großstädten ist keine vorübergehende Marktkorrektur, sondern Ergebnis jahrzehntelanger Vernachlässigung sozialer Wohnungspolitik: Der Rückzug des Staates aus dem sozialen Wohnungsbau und Deregulierungstendenzen haben einen Markt entstehen lassen, der Wohnen zur Kapitalanlage statt zur sozialen Grundversorgung macht.","Die Wohnungsnot in Deutschland ist eine Folge fehlender staatlicher Wohnungspolitik.","Wohnen ist in Deutschland zu teuer geworden, weil der Staat sich zurückgezogen hat.","Die Wohnungskrise zeigt, dass Deregulierung im Wohnungsmarkt gescheitert ist."],"correctAnswer":"Die Wohnungskrise in deutschen Großstädten ist keine vorübergehende Marktkorrektur, sondern Ergebnis jahrzehntelanger Vernachlässigung sozialer Wohnungspolitik: Der Rückzug des Staates aus dem sozialen Wohnungsbau und Deregulierungstendenzen haben einen Markt entstehen lassen, der Wohnen zur Kapitalanlage statt zur sozialen Grundversorgung macht."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Deregulierung hat Monopole entstehen ___.","options":["lassen","können","müssen","sollen"],"correctAnswer":"lassen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Do not allow any misunderstandings to arise","wordBankItems":["Lasse","keine","Missverständnisse","entstehen","."],"correctAnswer":"Lasse keine Missverständnisse entstehen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Verdrängen'' means?","options":["to displace","to push out","to expel","to marginalise"],"correctAnswer":"to displace"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002b1',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss noise and silence at B2","Use Lärm und Stille vocabulary","Talk about noise pollution, urban soundscapes, and Germany''s Lärmschutz policies"],"explanation":{"intro":"Noise and silence vocabulary covers noise pollution, health effects, and Germany''s sound landscape policies at B2.","culturalNote":"Lärm und Stille: Lärm (noise) is a major public health issue — WHO: >1 million healthy life years lost annually in Western Europe from traffic noise. Germany: Lärmschutzgesetz, TA Lärm (technical guidelines on noise). Night-time quiet laws: Nachtruhe (typically 10pm-6am), Sunday quiet (Sonntagsruhe — no lawn mowing). Major noise sources: Straßenverkehr (road traffic), Fluglärm (aircraft noise — Frankfurt Flughafen massive protests), Schienenverkehr (rail noise), Industrie. Health effects: Cardiovascular disease, sleep disruption, cognitive impairment in children (school near airports). Right to silence debate: Stille als Grundbedürfnis (silence as a basic need). Klanglandschaft (soundscape). Urban sound design."},"examples":[{"german":"Lärm ist die unterschätzte Umweltgefährdung: Während Luftverschmutzung sichtbar und messbar ist, wirkt chronischer Lärm unterhalb der Bewusstseinsschwelle und verursacht kardiologische, psychische und kognitive Schäden, die der Betroffene kaum dem Lärm selbst zurechnen kann.","english":"Noise is the underestimated environmental hazard: while air pollution is visible and measurable, chronic noise works below the threshold of consciousness and causes cardiological, psychological, and cognitive damage that the affected person can barely attribute to the noise itself."},{"german":"Stille ist in urbanen Räumen zur knappen Ressource geworden — und damit zum Gegenstand von Verteilungskonflikten: Parks und Ruhezonen sind nicht gleichmäßig über die Stadt verteilt, sondern konzentrieren sich in wohlhaberenden Stadtteilen, was den Zugang zur Stille zu einer Frage sozialer Gerechtigkeit macht.","english":"Silence has become a scarce resource in urban spaces — and thereby a subject of distributive conflicts: parks and quiet zones are not evenly distributed across the city, but are concentrated in affluent districts, which makes access to silence a matter of social justice."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss noise as a public health issue, silent zones, and urban sound at B2."}}',
'{"items":[{"word":"unterschätzt","translation":"underestimated","pronunciation":"oon-ter-SHÄTST","example":"Unterschätzte Gefahr."},{"word":"unterhalb der Bewusstseinsschwelle","translation":"below the threshold of consciousness","pronunciation":"oon-ter-HALB der beh-VOOST-zyns-shve-leh","example":"Unterhalb der Bewusstseinsschwelle."},{"word":"zurechnen","translation":"to attribute to","pronunciation":"TSOO-rekh-nen","example":"Dem Lärm zurechnen."},{"word":"knapp","translation":"scarce","pronunciation":"KNAP","example":"Knappe Ressource."},{"word":"der Verteilungskonflikt","translation":"distributive conflict","pronunciation":"dayr fer-TY-loonks-kon-flikt","example":"Verteilungskonflikt."},{"word":"wohlhabend","translation":"affluent","pronunciation":"VOHL-hah-bend","example":"Wohlhabende Stadtteile."}]}',
'{"title":"Zur knappen Ressource werden — to become a scarce resource (from abundance to scarcity)","pattern":"etwas wird zur knappen Ressource = something becomes a scarce resource (zur = to (a) + dative: zu + der = zur; knapp = scarce; werden + zu + dative = to become; the structure marks the transition into a new category)","explanation":"Werden + zu + dative = to become (status transition). Stille wird zur knappen Ressource = Silence becomes a scarce resource (zu + dative noun phrase: zur knappen Ressource). The pattern marks transformation into a new status (knapp = scarce — specifically economic scarcity term). Compare: als X gelten (to count as X — accepted classification), sich als X erweisen (to prove to be X — evidence), zu X mutieren (to mutate into X — negative connotation), sich zu X entwickeln (to develop into X — more process-oriented). Note: knapp (scarce) is specifically economic — more precise than selten (rare) or wenig (little).","examples":[{"sentence":"Trinkwasser wird weltweit zur knappen Ressource.","translation":"Drinking water is becoming a scarce resource worldwide."},{"sentence":"Zeit wird im modernen Leben zur knappsten Ressource.","translation":"Time is becoming the scarcest resource in modern life."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Unterschätzt'' means?","options":["underestimated","overlooked","neglected","ignored"],"correctAnswer":"underestimated"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Silence has become a scarce resource in urban spaces — and thereby a subject of distributive conflicts: parks and quiet zones are not evenly distributed across the city, but are concentrated in affluent districts, which makes access to silence a matter of social justice.","options":["Stille ist in urbanen Räumen zur knappen Ressource geworden — und damit zum Gegenstand von Verteilungskonflikten: Parks und Ruhezonen sind nicht gleichmäßig über die Stadt verteilt, sondern konzentrieren sich in wohlhaberenden Stadtteilen, was den Zugang zur Stille zu einer Frage sozialer Gerechtigkeit macht.","Stille wird in Städten immer seltener und nur reichen Stadtvierteln vorbehalten.","Ruhezonen in Städten sind ungleich verteilt — eine Frage der sozialen Gerechtigkeit.","In armen Stadtvierteln gibt es weniger grüne Räume und mehr Lärm."],"correctAnswer":"Stille ist in urbanen Räumen zur knappen Ressource geworden — und damit zum Gegenstand von Verteilungskonflikten: Parks und Ruhezonen sind nicht gleichmäßig über die Stadt verteilt, sondern konzentrieren sich in wohlhaberenden Stadtteilen, was den Zugang zur Stille zu einer Frage sozialer Gerechtigkeit macht."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Trinkwasser wird weltweit zur knappen ___.","options":["Ressource","Ware","Güte","Mangelware"],"correctAnswer":"Ressource"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Time is becoming the scarcest resource in modern life","wordBankItems":["Zeit","wird","im","modernen","Leben","zur","knappsten","Ressource","."],"correctAnswer":"Zeit wird im modernen Leben zur knappsten Ressource ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Wohlhabend'' means?","options":["affluent","wealthy","prosperous","well-off"],"correctAnswer":"affluent"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002b2',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss the self and others at B2","Use Das Selbst und die Anderen vocabulary","Talk about self and other in philosophy, social recognition, and intercultural contexts"],"explanation":{"intro":"Self and others vocabulary covers philosophy of self, social recognition, and the self-other relationship at B2.","culturalNote":"Das Selbst und die Anderen: Key philosophical tradition: Hegel''s Anerkennung (recognition — the self constitutes itself through recognition by others). Sartre: ''Die Hölle sind die anderen'' (Hell is other people). Emmanuel Levinas: the face of the Other as ethical call. Jürgen Habermas: intersubjective constitution of identity. Charles Taylor: sources of the self, social constitution of identity. Georg Herbert Mead (symbolic interactionism): ''I'' and ''me'' — the social self. Key social concepts: Stigma (Goffman), othering (Othering — treating as fundamentally different), Empathie (empathy), Perspektivwechsel (perspective change). In German: Nächstenliebe (love of neighbour), Fremdheit (strangeness/otherness), der Andere vs. das Andere (the other person vs. the other thing)."},"examples":[{"german":"Identität konstituiert sich nie im luftleeren Raum, sondern durch Prozesse sozialer Anerkennung: Wir werden, wer wir sind, im Spiegel des Anderen — die Anerkennung als kompetente Person, als zugehörig, als würdevoll ist keine bloße Zutat, sondern Bedingung gelingender Subjektivität.","english":"Identity never constitutes itself in an empty space, but through processes of social recognition: we become who we are in the mirror of the other — recognition as a competent person, as belonging, as dignified is not merely an ingredient, but a condition of successful subjectivity."},{"german":"''Othering'' bezeichnet den Prozess, durch den soziale Gruppen als fundamental anders konstruiert werden: Durch Abgrenzung vom Anderen konstituiert die In-Group ihre eigene Normalität — ein Mechanismus, der Ausgrenzung legitimiert und solidarische Praktiken mit dem ''Anderen'' erschwert.","english":"''Othering'' designates the process through which social groups are constructed as fundamentally different: through delimitation from the other, the in-group constitutes its own normality — a mechanism that legitimises exclusion and makes solidarity practices with the ''other'' more difficult."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Hegel''s recognition, Othering, and the social constitution of identity at B2."}}',
'{"items":[{"word":"luftleer","translation":"empty (void)","pronunciation":"LOOFT-layr","example":"Im luftleeren Raum."},{"word":"die Anerkennung","translation":"recognition","pronunciation":"dee AN-er-ken-oong","example":"Soziale Anerkennung."},{"word":"die Subjektivität","translation":"subjectivity","pronunciation":"dee zoob-yok-ti-vi-TÄT","example":"Gelingende Subjektivität."},{"word":"die Abgrenzung","translation":"delimitation","pronunciation":"dee AP-gren-tsoong","example":"Abgrenzung vom Anderen."},{"word":"das Othering","translation":"othering","pronunciation":"dahs AW-thering","example":"Othering praktizieren."},{"word":"legitimieren","translation":"to legitimise","pronunciation":"leh-gi-ti-MEER-en","example":"Ausgrenzung legitimieren."}]}',
'{"title":"Im Spiegel des Anderen — in the mirror of the other (social constitution of self)","pattern":"jemand wird im Spiegel des Anderen X = someone becomes X in the mirror of the other (Spiegel = mirror; des Anderen = genitive of der/das Andere = the other; the ''mirror of the other'' = how we see ourselves through others'' recognition)","explanation":"Im Spiegel des Anderen = in the mirror of the other. Wir werden, wer wir sind, im Spiegel des Anderen = We become who we are in the mirror of the other. This is a metaphor for social recognition theory (Hegel, Mead): the self is not pre-given but constituted through how others see us. Spiegel (mirror) is a key metaphor in German philosophy (Spiegelbild = mirror image, sich widerspiegeln = to be reflected). The genitive des Anderen marks possession: the other''s mirror. Compare: durch die Augen des Anderen (through the eyes of the other — perspective-taking), in der Wahrnehmung anderer (in others'' perception — more neutral), durch Fremdwahrnehmung (through external perception).","examples":[{"sentence":"Kinder entwickeln Selbstbewusstsein im Spiegel elterlicher Anerkennung.","translation":"Children develop self-confidence in the mirror of parental recognition."},{"sentence":"Das Selbstbild entsteht im Dialog mit dem Anderen.","translation":"The self-image arises in dialogue with the other."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Abgrenzung'' means?","options":["delimitation","boundary","separation","distinction"],"correctAnswer":"delimitation"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Identity never constitutes itself in an empty space, but through processes of social recognition: we become who we are in the mirror of the other — recognition as a competent person, as belonging, as dignified is not merely an ingredient, but a condition of successful subjectivity.","options":["Identität konstituiert sich nie im luftleeren Raum, sondern durch Prozesse sozialer Anerkennung: Wir werden, wer wir sind, im Spiegel des Anderen — die Anerkennung als kompetente Person, als zugehörig, als würdevoll ist keine bloße Zutat, sondern Bedingung gelingender Subjektivität.","Wir definieren uns durch die Anerkennung anderer — ohne Anerkennung keine Identität.","Identität ist sozial konstituiert: Wir werden, wer wir sind, durch andere.","Soziale Anerkennung ist eine notwendige Bedingung für ein gelingendes Leben."],"correctAnswer":"Identität konstituiert sich nie im luftleeren Raum, sondern durch Prozesse sozialer Anerkennung: Wir werden, wer wir sind, im Spiegel des Anderen — die Anerkennung als kompetente Person, als zugehörig, als würdevoll ist keine bloße Zutat, sondern Bedingung gelingender Subjektivität."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Kinder entwickeln Selbstbewusstsein im Spiegel elterlicher ___.","options":["Anerkennung","Liebe","Fürsorge","Unterstützung"],"correctAnswer":"Anerkennung"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The self-image arises in dialogue with the other","wordBankItems":["Das","Selbstbild","entsteht","im","Dialog","mit","dem","Anderen","."],"correctAnswer":"Das Selbstbild entsteht im Dialog mit dem Anderen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Legitimieren'' means?","options":["to legitimise","to justify","to authorise","to validate"],"correctAnswer":"to legitimise"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

